for line in SHORT.strip().splitlines():
    parts = line.split("|")
    if len(parts) != 20:
        raise SystemExit(f"short cols {len(parts)}: {parts[0]!r}")
    add(parts[0], *parts[1:])


extra_json = Path("/workspace/scripts/glossary-extra.json")
if extra_json.exists():
    import json as _json
    for src, vals in _json.loads(extra_json.read_text(encoding="utf-8")):
        RAW.append((src, vals))

# capitalize variants
extra = []
for src, vals in list(RAW):
    if src and src[0].islower():
        cap = src[0].upper() + src[1:]
        extra.append((cap, [(v[0].upper() + v[1:] if v else v) for v in vals]))
RAW.extend(extra)

# sort longest first, unique src
seen = set()
rows = []
def en_score(vals):
    en = vals[1] if len(vals) > 1 else ""
    return sum(ch in "çğıöşüÇĞİÖŞÜ" for ch in en)

for src, vals in sorted(RAW, key=lambda x: (-len(x[0]), en_score(x[1]), x[0])):
    if src in seen:
        continue
    seen.add(src)
    rows.append((src, vals))

# validate leftover catalog tokens get covered enough
cat = Path("/workspace/src/lib/catalog.ts").read_text()
names = re.findall(r'p\("[^"]+", "([^"]+)",', cat)
blurbs = re.findall(r'img\.\w+, "([^"]+)"', cat)

def apply(text: str, loc_i: int) -> str:
    out = text
    for src, vals in rows:
        if src in out:
            out = out.replace(src, vals[loc_i])
    return out

# leftover Turkish letters in EN
left = []
for n in names + blurbs:
    t = apply(n, 1)
    if re.search(r"[çğıöşüÇĞİÖŞÜ]", t):
        left.append((n, t))
print("glossary rows", len(rows))
print("untranslated leftovers", len(left))
for a, b in left[:40]:
    print("?", a, "=>", b)

out = ['import type { Locale } from "./i18n-locales";', "", "type Row = { src: string; map: Partial<Record<Locale, string>> };", "", "export const GLOSSARY: Row[] = ["]
for src, vals in rows:
    mp = ", ".join(f"{loc}: {json.dumps(val, ensure_ascii=False)}" for loc, val in zip(LOCALES, vals))
    out.append(f"  {{ src: {json.dumps(src, ensure_ascii=False)}, map: {{ {mp} }} }},")
out.append("];")
out.append("")
out.append("""export function translatePhrase(text: string, locale: Locale): string {
  if (locale === "tr") return text;
  let i = 0;
  let out = "";
  while (i < text.length) {
    let matched = false;
    for (const row of GLOSSARY) {
      if (!text.startsWith(row.src, i)) continue;
      const val = row.map[locale] ?? row.map.en;
      if (!val) continue;
      out += val;
      i += row.src.length;
      matched = true;
      break;
    }
    if (!matched) {
      out += text[i];
      i += 1;
    }
  }
  return out;
}
""")
Path("/workspace/src/lib/i18n-glossary.ts").write_text("\n".join(out), encoding="utf-8")
print("wrote", Path("/workspace/src/lib/i18n-glossary.ts").stat().st_size)
